class Schematic(BaseModel):
    """Is a visual diagram editor component for drawing system schematics, control
    flows, and process diagrams. Schematics support interactive symbols, connection
    handles, and dynamic state visualization.

    Attributes:
        key: Is the unique identifier for this schematic.
        name: Is a human-readable name for the schematic.
        nodes: Contains all diagram nodes in the schematic.
        edges: Contains all connections between nodes.
        configs: Contains per-node configuration keyed by node key. The variant of each
            value selects the symbol it configures.
        group: Is the group the schematic sits in, if any.
        project: Is the project that holds the schematic.
    """

    key: Key = Field(default_factory=uuid4)
    name: str
    nodes: list[Node] = Field(default_factory=list)
    edges: list[Edge] = Field(default_factory=list)
    configs: dict[str, NodeConfig] = Field(default_factory=dict)
    group: group_.Key | None = None
    project: project_.Key | None = None

    @_override
    def __hash__(self) -> int:
        return hash(self.key)


class RetrieveResponse(BaseModel):
    """Holds the schematics a RetrieveRequest selects.

    Attributes:
        schematics: Are the schematics the request selects.
    """

    schematics: list[Schematic] = Field(default_factory=list)


Where.model_rebuild()


TYPE_RESOURCE_ID = ID(type="schematic")


def resource_id(key: Key) -> ID:
    return ID(type="schematic", key=str(key))
